// Package airportdata exposes the embedded OurAirports dataset used by the
// flight planner. The data is public domain (Unlicense) and generated by
// tools/gen-airports.py.
package airportdata

import (
	"compress/gzip"
	"embed"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"
	"sync"
)

//go:embed airports.json.gz
var embedded embed.FS

// Airport is one searchable airport. The DCS fields are filled when the API
// merges an aerodrome from the simulator's own terrain data.
type Airport struct {
	Ident        string  `json:"ident"`
	ICAO         string  `json:"icao,omitempty"`
	IATA         string  `json:"iata,omitempty"`
	Name         string  `json:"name"`
	Type         string  `json:"type,omitempty"`
	Lat          float64 `json:"lat"`
	Lon          float64 `json:"lon"`
	ElevationFt  int     `json:"elevationFt,omitempty"`
	Country      string  `json:"country,omitempty"`
	Municipality string  `json:"municipality,omitempty"`

	// Source is "ourairports" for the embedded dataset, "dcs" for an airfield
	// read from the simulator.
	Source  string  `json:"source,omitempty"`
	Theatre string  `json:"theatre,omitempty"`
	Tower   float64 `json:"tower,omitempty"`
	TACAN   string  `json:"tacan,omitempty"`
	ILS     []ILS   `json:"ils,omitempty"`
}

// ILS is one instrument landing system of a DCS airfield.
type ILS struct {
	Runway string  `json:"runway"`
	MHz    float64 `json:"mhz"`
}

// Result is a scored search hit.
type Result struct {
	Airport
	Score int `json:"-"`
}

type payload struct {
	Source    string    `json:"source"`
	License   string    `json:"license"`
	Generated string    `json:"generated"`
	Airports  []Airport `json:"airports"`
}

type entry struct {
	Airport
	ident string
	name  string
	city  string
}

// Catalog is the loaded dataset. It is safe to use concurrently after Load.
type Catalog struct {
	entries   []entry
	generated string
	source    string
}

var (
	once    sync.Once
	catalog *Catalog
	loadErr error
)

// Load decodes the embedded dataset once.
func Load() (*Catalog, error) {
	once.Do(func() {
		file, err := embedded.Open("airports.json.gz")
		if err != nil {
			loadErr = err
			return
		}
		defer file.Close()
		reader, err := gzip.NewReader(file)
		if err != nil {
			loadErr = err
			return
		}
		defer reader.Close()
		data, err := io.ReadAll(reader)
		if err != nil {
			loadErr = err
			return
		}
		var body payload
		if err := json.Unmarshal(data, &body); err != nil {
			loadErr = err
			return
		}
		items := make([]entry, 0, len(body.Airports))
		for _, item := range body.Airports {
			if item.Source == "" {
				item.Source = "ourairports"
			}
			items = append(items, entry{
				Airport: item,
				ident:   normalize(item.Ident + " " + item.ICAO + " " + item.IATA),
				name:    normalize(item.Name),
				city:    normalize(item.Municipality),
			})
		}
		catalog = &Catalog{entries: items, generated: body.Generated, source: body.Source}
	})
	if loadErr != nil {
		return nil, fmt.Errorf("airport dataset: %w", loadErr)
	}
	return catalog, nil
}

// Generated reports the dataset date, for the UI.
func (c *Catalog) Generated() string { return c.generated }

// Count reports how many airports are embedded.
func (c *Catalog) Count() int { return len(c.entries) }

// Search returns the best matches for q, limited to limit entries. Exact
// identifiers rank first, then prefixes, then name and city matches. Large
// airports win ties against small fields.
func (c *Catalog) Search(q string, limit int) []Result {
	query := normalize(q)
	if query == "" || len(c.entries) == 0 {
		return nil
	}
	if limit <= 0 || limit > 100 {
		limit = 20
	}
	matches := make([]Result, 0, limit)
	for _, item := range c.entries {
		score := scoreEntry(query, item)
		if score == 0 {
			continue
		}
		matches = append(matches, Result{Airport: item.Airport, Score: score})
	}
	sortResults(matches)
	if len(matches) > limit {
		matches = matches[:limit]
	}
	return matches
}

// ScoreQuery scores one airport against a raw query. It is used by the API to
// rank DCS airfields with the same rules as the embedded dataset.
func ScoreQuery(q string, a Airport) int {
	query := normalize(q)
	if query == "" {
		return 0
	}
	return scoreNormalized(query, normalize(a.Ident+" "+a.ICAO+" "+a.IATA), normalize(a.Name), normalize(a.Municipality), a.Type)
}

func scoreEntry(query string, item entry) int {
	return scoreNormalized(query, item.ident, item.name, item.city, item.Type)
}

func scoreNormalized(query, ident, name, city, kind string) int {
	score := 0
	for _, token := range strings.Fields(ident) {
		if token == query {
			score = 1000
			break
		}
	}
	switch {
	case score > 0:
	case strings.HasPrefix(ident, query):
		score = 800
	case strings.HasPrefix(name, query):
		score = 600
	case strings.HasPrefix(city, query):
		score = 400
	case strings.Contains(name, query):
		score = 250
	case strings.Contains(ident, query):
		score = 200
	case strings.Contains(city, query):
		score = 100
	}
	if score == 0 {
		return 0
	}
	switch kind {
	case "large":
		score += 30
	case "medium":
		score += 20
	case "small":
		score += 10
	}
	return score
}

func sortResults(items []Result) {
	sort.SliceStable(items, func(i, j int) bool {
		if items[i].Score != items[j].Score {
			return items[i].Score > items[j].Score
		}
		// Prefer the DCS entry: it carries the simulator's own frequencies.
		if (items[i].Source == "dcs") != (items[j].Source == "dcs") {
			return items[i].Source == "dcs"
		}
		return items[i].Ident < items[j].Ident
	})
}

// Dedupe merges the DCS hits into the dataset hits. A DCS airfield replaces the
// OurAirports row with the same ICAO: same place, richer simulator data.
func Dedupe(base, extra []Result, limit int) []Result {
	byCode := map[string]bool{}
	for _, item := range extra {
		for _, code := range dedupeCodes(item.Airport) {
			byCode[code] = true
		}
	}
	seen := map[string]bool{}
	combined := make([]Result, 0, len(base)+len(extra))
	appendItem := func(item Result) {
		codes := dedupeCodes(item.Airport)
		key := ""
		if len(codes) > 0 {
			key = codes[0]
		}
		if key == "" {
			key = "ident:" + strings.ToUpper(item.Ident)
		}
		if seen[key] {
			return
		}
		seen[key] = true
		combined = append(combined, item)
	}
	for _, item := range extra {
		appendItem(item)
	}
	for _, item := range base {
		replaced := false
		for _, code := range dedupeCodes(item.Airport) {
			if byCode[code] {
				replaced = true
				break
			}
		}
		if replaced {
			continue
		}
		appendItem(item)
	}
	sortResults(combined)
	if limit > 0 && len(combined) > limit {
		combined = combined[:limit]
	}
	return combined
}

func dedupeCodes(a Airport) []string {
	var codes []string
	if value := strings.ToUpper(strings.TrimSpace(a.ICAO)); value != "" {
		codes = append(codes, "icao:"+value)
	}
	if value := strings.ToUpper(strings.TrimSpace(a.Ident)); value != "" {
		codes = append(codes, "ident:"+value)
	}
	return codes
}

// normalize folds a string for case- and accent-insensitive search.
func normalize(value string) string {
	var builder strings.Builder
	builder.Grow(len(value))
	lastSpace := true
	for _, r := range strings.ToUpper(value) {
		r = fold(r)
		if r == ' ' || r == '\t' || r == '\n' || r == '-' || r == '_' {
			if !lastSpace {
				builder.WriteByte(' ')
				lastSpace = true
			}
			continue
		}
		builder.WriteRune(r)
		lastSpace = false
	}
	return strings.TrimSpace(builder.String())
}

func fold(r rune) rune {
	switch r {
	case 'À', 'Á', 'Â', 'Ã', 'Ä', 'Å':
		return 'A'
	case 'Ç':
		return 'C'
	case 'È', 'É', 'Ê', 'Ë':
		return 'E'
	case 'Ì', 'Í', 'Î', 'Ï':
		return 'I'
	case 'Ñ':
		return 'N'
	case 'Ò', 'Ó', 'Ô', 'Õ', 'Ö', 'Ø':
		return 'O'
	case 'Ù', 'Ú', 'Û', 'Ü':
		return 'U'
	case 'Ý', 'Ÿ':
		return 'Y'
	case 'Æ':
		return 'A'
	case 'Œ':
		return 'O'
	}
	return r
}
